import json,hashlib,os
root="/Users/wahrfreiheit/OMP/hungary-socialist-mechanism-lab"; os.chdir(root)
base="config/inference/hist_vnext_v1/"
m=json.load(open(base+"EVIDENCE_MANIFEST.json"))
def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
stale=[];ok=0
def walk(o):
    global ok
    if isinstance(o,dict):
        p=o.get("path"); s=o.get("sha256"); b=o.get("bytes")
        if isinstance(p,str) and isinstance(s,str):
            fp=base+p
            if os.path.exists(fp):
                if sha(fp)!=s or (isinstance(b,int) and os.path.getsize(fp)!=b): stale.append(p)
                else: ok+=1
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(m)
print("supervisor manifest entries matching disk:", ok)
print("stale (supervisor must rebuild at final seal):", stale)

